  const state={idle:'未开始',playing:'朗读中',paused:'已暂停',interrupted:'已中断',probing:'正在检查朗读可用性',preparing:'准备中',resuming:'准备中',completed:'已完成',stopping:'停止中',error:'播放失败',failed:'播放失败',unavailable:'当前引擎不可用'}[status]||'未开始';
